#!/usr/bin/env node
/**
 * Generates `database/schema.sql` — a plain MySQL dump of the Prisma schema.
 *
 * Why this exists: some hosts only offer phpMyAdmin, with no way to run
 * `prisma db push` or `prisma migrate deploy`. Importing this file creates the
 * same tables, indexes and foreign keys the application expects.
 *
 * The DDL is generated by the Prisma CLI itself rather than hand-written, so it
 * can never drift from `prisma/schema.prisma`. Re-run this script after every
 * schema change.
 */
import { execFileSync } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, "..");
const schemaFile = join(root, "prisma", "schema.prisma");
const outFile = join(root, "database", "schema.sql");

// Resolve the Prisma CLI entry point across layouts. The published package
// exposes `build/index.js`, but keep a fallback so a global/hoisted install
// does not break the script.
const cliCandidates = [
  join(root, "node_modules", "prisma", "build", "index.js"),
  join(root, "node_modules", ".bin", "prisma"),
];

function prismaArgs(args) {
  for (const cli of cliCandidates) {
    try {
      const out = execFileSync(process.execPath, [cli, ...args], {
        cwd: root,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "pipe"],
      });
      return out;
    } catch (error) {
      // ENOENT means "this candidate is not there" — try the next one. Any
      // other failure is a real Prisma error and should surface immediately.
      if (error?.code === "ENOENT") continue;
      throw error;
    }
  }
  throw new Error(
    "Could not find the Prisma CLI. Run `npm install` inside backend/ first.",
  );
}

console.log("Generating database/schema.sql from prisma/schema.prisma …");

const ddl = prismaArgs([
  "migrate",
  "diff",
  "--from-empty",
  "--to-schema-datamodel",
  schemaFile,
  "--script",
]);

if (!/CREATE TABLE/.test(ddl)) {
  throw new Error("Prisma produced no DDL — refusing to write an empty schema.sql.");
}

const header = [
  "-- TechCiti Tutor Report Portal — database schema",
  "--",
  "-- Generated by `npm run db:sql`. DO NOT EDIT BY HAND: the file is derived",
  "-- from prisma/schema.prisma and will be overwritten on the next run.",
  "--",
  "-- Target: MySQL 8 / MariaDB 10.4+ (InnoDB, utf8mb4).",
  "--",
  "-- Usage:",
  "--   1. Create an empty database named `techciti_reports`.",
  "--   2. Import this file through phpMyAdmin (Import tab) or from a shell:",
  "--        mysql -u root -p techciti_reports < database/schema.sql",
  "--   3. Load the demo data with `npm run seed`.",
  "--",
  `-- Tables: ${[...ddl.matchAll(/CREATE TABLE `([^`]+)`/g)].map((m) => m[1]).join(", ")}`,
  "",
  "SET NAMES utf8mb4;",
  "SET FOREIGN_KEY_CHECKS = 0;",
  "",
  "",
].join("\n");

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, `${header}${ddl.trimEnd()}\n\nSET FOREIGN_KEY_CHECKS = 1;\n`, "utf8");

const tableCount = [...ddl.matchAll(/CREATE TABLE `([^`]+)`/g)].length;
console.log(`  wrote ${outFile}`);
console.log(`  ${tableCount} tables, ${[...ddl.matchAll(/ADD CONSTRAINT/g)].length} foreign keys`);